import { formatType } from '../types/phpType';
import type { ViewVariables } from './collectViewVariables';

/**
 * The generated block at the top of a view. Everything between the two markers belongs to
 * ViewSense and is rewritten on each update; the rest of the file is never touched.
 *
 * A view that starts with HTML gets its own PHP tag:
 *
 *     <?php /* viewsense:start - generated by ViewSense, do not edit *\/
 *     /** @var string $title *\/
 *     /* viewsense:end *\/ ?>
 *     <h1>...
 *
 * A view that starts with `<?php` gets the block right after that tag, so a
 * `declare(strict_types=1)` statement can still come first.
 */
const START_MARKER = '/* viewsense:start - generated by ViewSense, do not edit */';
const END_MARKER = '/* viewsense:end */';

/** An existing block with its own PHP tag. PHP drops the line break right after `?>`. */
const STANDALONE_BLOCK =
  /^<\?php \/\* viewsense:start[^\n]*\n[\s\S]*?\/\* viewsense:end \*\/ \?>\r?\n?/;
/** An existing block inside the first PHP tag of the file. */
const INLINE_BLOCK = /\/\* viewsense:start[^\n]*\n[\s\S]*?\/\* viewsense:end \*\/\r?\n?/;
/** A file that starts with `<?php` and a line break, or `<?php declare(...)` on one line. */
const OPENING_TAG = /^<\?php(?:[ \t]*\r?\n|[ \t]+(?=declare\b))/i;

const BYTE_ORDER_MARK = '\u{FEFF}';

/** One `@var` line per variable: `$this` first, then by name so the block stays stable. */
export function renderVarLines(variables: ViewVariables): string[] {
  const order = (name: string): string => (name === 'this' ? '' : name);
  return [...variables]
    .sort(([a], [b]) => order(a).localeCompare(order(b)))
    .map(([name, type]) => `/** @var ${formatType(type)} $${name} */`);
}

/**
 * Returns the view source with an up-to-date block. With no variables, the block is removed.
 * Keeps the file's line endings and byte order mark.
 */
export function applyHintBlock(source: string, variables: ViewVariables): string {
  const bom = source.startsWith(BYTE_ORDER_MARK) ? BYTE_ORDER_MARK : '';
  const body = removeHintBlock(source.slice(bom.length));
  const lines = renderVarLines(variables);
  if (lines.length === 0) {
    return bom + body;
  }

  const eol = body.includes('\r\n') ? '\r\n' : '\n';
  const inner = [START_MARKER, ...lines, END_MARKER];

  const openingTag = OPENING_TAG.exec(body);
  if (openingTag !== null) {
    const tag = openingTag[0];
    // `<?php declare(...)` on one line: put the block on its own lines after the tag.
    const head = tag.endsWith('\n') ? tag : `<?php${eol}`;
    return bom + head + inner.join(eol) + eol + body.slice(tag.length);
  }

  return bom + `<?php ${inner.join(eol)} ?>${eol}` + body;
}

export function hasHintBlock(source: string): boolean {
  return INLINE_BLOCK.test(source);
}

/**
 * First and last line (0-based) of the block, from the `viewsense:start` marker to the
 * `viewsense:end` marker, or `null` when the view has no block.
 */
export function hintBlockLines(source: string): { start: number; end: number } | null {
  const match = /\/\* viewsense:start[\s\S]*?\/\* viewsense:end \*\//.exec(source);
  if (match === null) {
    return null;
  }
  const lineAt = (offset: number): number => source.slice(0, offset).split('\n').length - 1;
  return { start: lineAt(match.index), end: lineAt(match.index + match[0].length) };
}

/** Removes the block, whichever form it has. */
export function removeHintBlock(source: string): string {
  if (STANDALONE_BLOCK.test(source)) {
    return source.replace(STANDALONE_BLOCK, '');
  }
  return source.replace(INLINE_BLOCK, '');
}
